import{_ as i,C as d,o as a,c as n,aj as e,E as s}from"./framework.js";const m=JSON.parse('{"title":"元素属性 | Cms / Content | Documentation","description":"元素属性（引擎中的 KConfig）用于在后台集中修改模板里某段 HTML 标签的可编辑属性（如 href、src、标签内 HTML 等），而不用每次改 Page/View 源码。条目来自模板中的 k-config 标记；本页不能凭空新建一条配置，也没有「新建」按钮。","frontmatter":{"title":"元素属性 | Cms / Content | Documentation","description":"元素属性（引擎中的 KConfig）用于在后台集中修改模板里某段 HTML 标签的可编辑属性（如 href、src、标签内 HTML 等），而不用每次改 Page/View 源码。条目来自模板中的 k-config 标记；本页不能凭空新建一条配置，也没有「新建」按钮。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/content/tag-attributes.html"}]]},"headers":[],"relativePath":"zh/cms/content/tag-attributes.md","filePath":"cms/content/tag-attributes.md","lastUpdated":1780296726000}'),r={name:"zh/cms/content/tag-attributes.md"};function c(l,t,h,g,k,p){const o=d("DocImage");return a(),n("div",null,[t[0]||(t[0]=e(`<h1 id="元素属性" tabindex="-1">元素属性 <a class="header-anchor" href="#元素属性" aria-label="Permalink to &quot;元素属性&quot;">​</a></h1><blockquote><p>菜单：<strong>内容 → 元素属性</strong>（路由 <code>text</code>；须在 <strong>编辑菜单</strong> 中勾选显示）<br> 深链：<code>/_Admin/content/text?SiteId={站点GUID}</code></p></blockquote><p><strong>元素属性</strong>（引擎中的 <strong>KConfig</strong>）用于在后台<strong>集中修改</strong>模板里某段 HTML 标签的可编辑属性（如 <code>href</code>、<code>src</code>、标签内 HTML 等），而不用每次改 Page/View 源码。条目来自模板中的 <strong><code>k-config</code></strong> 标记；本页<strong>不能凭空新建</strong>一条配置，也没有「新建」按钮。</p><div class="tip custom-block"><p class="custom-block-title">冷门但有用</p><p>适合「页脚链接地址」「某张图的 <code>src</code>」「某段可替换的块级 HTML」等需要在多处页面复用、又希望运营在后台改属性的场景。若只是改几个字的多语言文案，用 <a href="./labels.html">标签</a>；若是一整块复用 HTML，用 <a href="./html-blocks.html">HTML 片段</a>。</p></div><div class="warning custom-block"><p class="custom-block-title">与「标签」、内容条目无关</p><table tabindex="0"><thead><tr><th></th><th><strong>元素属性</strong>（本页）</th><th><a href="./labels.html">标签</a></th><th><a href="./contents-entries.html">内容条目</a></th></tr></thead><tbody><tr><td>路由</td><td><code>/content/text</code></td><td><code>/content/labels</code></td><td><code>/content/content</code></td></tr><tr><td>数据</td><td>KConfig：HTML 属性键值</td><td>Label：多语言字符串</td><td>TextContent：内容夹字段</td></tr><tr><td>模板标记</td><td><code>k-config=&quot;键名&quot;</code></td><td><code>k.label()</code> / <code>k.t()</code></td><td><code>k.content</code> / k-data</td></tr></tbody></table></div><h2 id="原理简述" tabindex="-1">原理简述 <a class="header-anchor" href="#原理简述" aria-label="Permalink to &quot;原理简述&quot;">​</a></h2><p>在 Page、Layout 或 View 的 HTML 上为元素加上 <strong><code>k-config=&quot;唯一键名&quot;</code></strong>（也可用 <code>v-config</code>，与引擎绑定一致）。站点<strong>渲染或保存</strong>相关页面时，Kooboo 会登记或更新对应的 KConfig 记录，并抽出可编辑属性到 <strong>binding</strong> 字典（如 <code>href</code>、<code>src</code>、<code>innerHtml</code> 等）。</p><p>渲染输出时，<code>k-config</code> 属性本身不会出现在最终 HTML 中；各 binding 的值会写回对应属性。</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 示例：页脚链接，键名 footer-home --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> k-config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;footer-home&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;footer-link&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;首页&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 示例：图片 src 可在本页或媒体库中改 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> k-config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;logo-main&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/images/logo.png&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> alt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Logo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">哪些属性会进 binding？</p><p>一般 <strong>普通 HTML 属性</strong>（如 <code>href</code>、<code>src</code>、<code>class</code>、<code>id</code>）会纳入；<strong><code>style</code></strong>、<strong><code>on*</code> 事件</strong>、名称中含 <strong><code>-</code> / <code>_</code></strong> 的属性通常保持静态，不在此页编辑（以引擎 <code>IsIgnoreAttribute</code> 为准）。非自闭合标签还会包含 <strong><code>innerHtml</code></strong>（标签内部 HTML）。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>在 <a href="./../navigation.html#权限与编辑菜单">编辑菜单</a> 中勾选 <strong>元素属性</strong>。</li><li>左侧 <strong>内容 → 元素属性</strong>。</li><li>若列表为空，请先在模板中加入 <code>k-config</code> 并保存/访问相关页面，让系统生成条目。</li></ol>`,12)),s(o,{src:"/cms/content/tag-attributes-list.png",alt:"元素属性列表",width:"1120"}),t[1]||(t[1]=e('<h2 id="列表页" tabindex="-1">列表页 <a class="header-anchor" href="#列表页" aria-label="Permalink to &quot;列表页&quot;">​</a></h2><table tabindex="0"><thead><tr><th>列 / 操作</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>KConfig 的 <strong>键名</strong>（即 <code>k-config</code> 的值）或显示名；副标题为 binding 中第一项的摘要（如 <code>href: /</code>）</td></tr><tr><td>预览</td><td>若标签为 <strong><code>img</code></strong> 且 binding 含 <strong><code>src</code></strong>，显示缩略图</td></tr><tr><td>标签名</td><td>原始 HTML 标签，如 <code>&lt;a&gt;</code>、<code>&lt;img&gt;</code>；悬停可看 <code>tagHtml</code> 片段</td></tr><tr><td>引用</td><td>被哪些 Page / Layout / View 等引用</td></tr><tr><td>最后修改</td><td>更新时间</td></tr><tr><td><strong>编辑</strong></td><td>修改 binding；<code>img</code> 的 <code>src</code> 改为打开 <a href="/kb-docs/zh/cms/site/media.html">媒体库</a> 选图</td></tr><tr><td><strong>版本</strong></td><td>版本历史（权限允许时）</td></tr></tbody></table><p>支持勾选后 <strong>批量删除</strong>（权限 <code>text</code> · <code>delete</code>）。</p><h2 id="编辑弹窗" tabindex="-1">编辑弹窗 <a class="header-anchor" href="#编辑弹窗" aria-label="Permalink to &quot;编辑弹窗&quot;">​</a></h2><p>标题为 <strong>元素属性</strong>。每个 <strong>binding 键</strong> 一行（多行文本框），例如：</p><table tabindex="0"><thead><tr><th>键</th><th>含义（常见）</th></tr></thead><tbody><tr><td><code>href</code></td><td>链接地址</td></tr><tr><td><code>src</code></td><td>图片/资源 URL</td></tr><tr><td><code>innerHtml</code></td><td>标签内部 HTML（非自闭合标签）</td></tr><tr><td><code>class</code> / <code>id</code> 等</td><td>其它可编辑属性</td></tr></tbody></table><p>保存后写入站点 KConfig，后续请求按新值渲染。</p><div class="tip custom-block"><p class="custom-block-title"><code>img</code> 与 <code>src</code></p><p>标签名为 <strong><code>img</code></strong> 时，编辑 <strong><code>src</code></strong> 将直接弹出 <strong>媒体库</strong> 选择器（与列表行内逻辑一致），选图后写回 binding。</p></div>',8)),s(o,{src:"/cms/content/tag-attributes-edit.png",alt:"编辑元素属性：修改 href、innerHtml 等 binding",width:"960"}),t[2]||(t[2]=e('<h2 id="与在线编辑" tabindex="-1">与在线编辑 <a class="header-anchor" href="#与在线编辑" aria-label="Permalink to &quot;与在线编辑&quot;">​</a></h2><p><a href="/kb-docs/zh/cms/site/pages-inline-edit.html">在线编辑</a> 中若选中带 <code>k-config</code> 的元素，可快捷打开同一套编辑弹窗（提示一般为立即生效类文案）。适合在预览页上改链接或图片，无需进本列表。</p><h2 id="典型流程" tabindex="-1">典型流程 <a class="header-anchor" href="#典型流程" aria-label="Permalink to &quot;典型流程&quot;">​</a></h2><ol><li>开发在 View 或 Page 中为元素添加 <code>k-config=&quot;promo-banner&quot;</code> 及初始 <code>href</code>、<code>innerHtml</code> 等。</li><li>保存并预览/发布页面，使 KConfig 出现在 <strong>元素属性</strong> 列表。</li><li>运营在本页或 <strong>在线编辑</strong> 中修改 <code>href</code> / <code>innerHtml</code> 等。</li><li>用 <strong>引用</strong> 列确认仍被哪些页面使用；无用条目可删除。</li></ol><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./">内容模块概述</a></td><td>内容分组菜单</td></tr><tr><td><a href="./../navigation.html#权限与编辑菜单">编辑菜单</a></td><td>显示本菜单</td></tr><tr><td><a href="/kb-docs/zh/cms/site/pages-inline-edit.html">在线编辑</a></td><td>预览页改 KConfig</td></tr><tr><td><a href="/kb-docs/zh/templateEngine/page/">模板引擎 · Page</a></td><td>编写带 <code>k-config</code> 的 HTML</td></tr><tr><td><a href="./labels.html">标签</a></td><td>多语言短文案（非本功能）</td></tr></tbody></table>',6))])}const f=i(r,[["render",c]]);export{m as __pageData,f as default};
